import java.net.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.regex.*;import javax.crypto.*;import javax.crypto.spec.*;
public class PhotoNetworkPeer {
 static byte[] key=new byte[32];static{for(int i=0;i<32;i++)key[i]=(byte)i;}
 static byte[] seal(byte[] clear,String reference)throws Exception{byte[] nonce=new byte[12];new SecureRandom().nextBytes(nonce);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(("CoolSync/media/1|"+reference).getBytes(StandardCharsets.UTF_8));byte[] encrypted=c.doFinal(clear),out=new byte[12+encrypted.length];System.arraycopy(nonce,0,out,0,12);System.arraycopy(encrypted,0,out,12,encrypted.length);return out;}
 static String open(byte[] bytes)throws Exception{byte[] raw=Base64.getDecoder().decode(new String(bytes,StandardCharsets.US_ASCII).trim());Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,Arrays.copyOfRange(raw,0,12)));c.updateAAD("CoolSync/1".getBytes(StandardCharsets.UTF_8));return new String(c.doFinal(Arrays.copyOfRange(raw,12,raw.length)),StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{ServerSocket server=new ServerSocket(0,10,InetAddress.getByName("127.0.0.1"));Files.writeString(Path.of(args[0]),""+server.getLocalPort());byte[] image=Files.readAllBytes(Path.of(args[1]));
  while(true){try(Socket socket=server.accept()){socket.setSoTimeout(10000);DataInputStream input=new DataInputStream(socket.getInputStream());DataOutputStream output=new DataOutputStream(socket.getOutputStream());String line=input.readLine();if(line==null)continue;boolean thumbnail=line.startsWith("POST /thumbnail ");if(!thumbnail&&!line.startsWith("POST /catalog "))throw new AssertionError("wrong route");int length=0;while(!(line=input.readLine()).isEmpty()){if(line.toLowerCase().startsWith("content-length:"))length=Integer.parseInt(line.substring(line.indexOf(':')+1).trim());}if(length<1||length>65536)throw new AssertionError("wrong size");String request=open(input.readNBytes(length));if(!request.contains("fixture-token")||!request.contains(thumbnail ? "mediaThumb":"mediaCatalog")||!request.contains("\"role\":\"mac\""))throw new AssertionError("request auth");Matcher match=Pattern.compile("\"id\"\\s*:\\s*\"([^\"]+)\"").matcher(request);if(!match.find())throw new AssertionError("missing reference");String id=match.group(1);
   if(request.contains("eof"))continue;if(request.contains("wait"))Thread.sleep(700);
   byte[] clear=thumbnail ? image:("{\"ok\":true,\"payload\":\""+"한글".repeat(40000)+"\"}").getBytes(StandardCharsets.UTF_8);
   byte[] encrypted=request.contains("oversize") ? new byte[512001]:seal(clear,request.contains("wrongref") ? "invalid":id);if(request.contains("tamper"))encrypted[encrypted.length/2]^=1;
   output.write(("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: "+encrypted.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));output.write(encrypted);output.flush();
  }catch(Exception e){System.err.println(e.getClass().getSimpleName());}}
 }
}
